'use client';

import { useEffect, useState } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';
import PropertyCard from '../components/PropertyCard';
import { useAuth } from '../../lib/AuthContext';
import Image from 'next/image';
import ProjectListingCard from '../components/ProjectListingCard';
import Link from 'next/link';
import FeaturedProjectCard from '../components/FeaturedProjectCard';
import Footer from '../components/Footer';

interface Project {
  id: string;
  name: string;
  description: string;
  developer: { 
    id: string;
    name: string; 
  } | null;
  city: {
    id: string;
    name: string;
  } | null;
  locality: {
    id: string;
    name: string;
  } | null;
  possession_status: string;
  price_range: {
    min: number;
    max: number;
    currency: string;
  };
  cover_image_url: string;
  amenities: string[];
  created_at: string;
  is_active: boolean;
  project_size: {
    total_area: number;
    unit: string;
    built_up_area: number;
  };
}

// Add interface for database response
interface DatabaseProject {
  id: string;
  name: string;
  description: string;
  developer: { id: string; name: string; }[] | null;
  city: { id: string; name: string; }[] | null;
  locality: { id: string; name: string; }[] | null;
  possession_status: string;
  price_range: {
    min: number;
    max: number;
    currency: string;
  };
  cover_image_url: string;
  amenities: string[];
  created_at: string;
  is_active: boolean;
  project_size: {
    total_area: number;
    unit: string;
    built_up_area: number;
  };
}

interface Filters {
  priceRange: string;
  propertyType: string;
  city: string;
  locality: string;
  status: string;
  sortBy: string;
}

// Add interface for the card props
interface ProjectCardData {
  id: string;
  name: string;
  developer_name: string;
  developer_id: string;
  city: string;
  locality: string;
  starting_price: number;
  image_url: string;
  property_type: string;
  total_units: number;
  status: string;
  amenities: string[];
}

// Helper function to convert Project to ProjectCardData
const convertToCardData = (project: Project): ProjectCardData => ({
  id: project.id,
  name: project.name,
  developer_name: project.developer?.name || 'Unknown Developer',
  developer_id: project.developer?.id || '',
  city: project.city?.name || 'Unknown City',
  locality: project.locality?.name || 'Unknown Locality',
  starting_price: project.price_range.min,
  image_url: project.cover_image_url,
  property_type: 'apartment',
  total_units: 0,
  status: project.is_active ? 'active' : 'inactive',
  amenities: project.amenities || []
});

export default function ListingsPage() {
  const { user } = useAuth();
  const supabase = createClientComponentClient();
  const [searchQuery, setSearchQuery] = useState('');
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [filters, setFilters] = useState<Filters>({
    priceRange: '',
    propertyType: '',
    city: '',
    locality: '',
    status: '',
    sortBy: 'newest'
  });
  const [cities, setCities] = useState<string[]>([]);
  const [localities, setLocalities] = useState<string[]>([]);
  const itemsPerPage = 30;

  useEffect(() => {
    fetchCities();
  }, []);

  useEffect(() => {
    if (filters.city) {
      fetchLocalities(filters.city);
    } else {
      setLocalities([]);
    }
  }, [filters.city]);

  useEffect(() => {
    fetchProjects();
  }, [currentPage, filters, searchQuery]);

  const fetchCities = async () => {
    try {
      const { data, error } = await supabase
        .from('cities')
        .select('name')
        .order('name');

      if (error) throw error;
      setCities(data.map(city => city.name));
    } catch (err) {
      console.error('Error fetching cities:', err);
      setCities([]);
    }
  };

  const fetchLocalities = async (cityName: string) => {
    try {
      const { data: cityData, error: cityError } = await supabase
        .from('cities')
        .select('id')
        .eq('name', cityName)
        .single();

      if (cityError) throw cityError;

      const { data, error } = await supabase
        .from('localities')
        .select('name')
        .eq('city_id', cityData.id)
        .order('name');

      if (error) throw error;
      setLocalities(data.map(locality => locality.name));
    } catch (err) {
      console.error('Error fetching localities:', err);
      setLocalities([]);
    }
  };

  const fetchProjects = async () => {
    setLoading(true);
    try {
      // Fetch projects with developer info using the correct join alias
      const { data, error, count } = await supabase
        .from('projects')
        .select(`
          id,
          name,
          developer_id,
          price_range,
          amenities,
          cover_image_url,
          developer:developers!developer_id (
            id,
            name
          )
        `, { count: 'exact' });

      if (error) {
        console.error('Database query error:', error);
        throw error;
      }

      if (!data) {
        setProjects([]);
        setTotalCount(0);
        return;
      }

      // Log the raw data to verify what we're getting
      console.log('Raw data from database:', data.map(item => ({
        projectId: item.id,
        developer: item.developer
      })));

      const basicProjects = data.map(item => {
        // Supabase may return developer as an array even for one-to-one relationships
        let developer = null;
        if (Array.isArray(item.developer)) {
          developer = item.developer.length > 0 ? item.developer[0] : null;
        } else {
          developer = item.developer || null;
        }

        // Log the processed developer data
        console.log('Processed project data:', {
          projectId: item.id,
          developerName: developer?.name,
          developerId: developer?.id
        });

        return {
          id: item.id,
          name: item.name,
          description: '',
          developer: developer, // This will be { id: string, name: string } | null
          city: null,
          locality: null,
          possession_status: '',
          price_range: item.price_range || { min: 0, max: 0, currency: 'INR' },
          cover_image_url: item.cover_image_url || '/placeholder-project.jpg',
          amenities: item.amenities || [],
          created_at: new Date().toISOString(),
          is_active: true,
          project_size: { total_area: 0, unit: 'sq.ft', built_up_area: 0 }
        } as Project;
      });

      setProjects(basicProjects);
      setTotalCount(count || 0);

    } catch (err) {
      console.error('Error in fetchProjects:', err);
      setProjects([]);
      setTotalCount(0);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (filterType: keyof Filters, value: string) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
    setCurrentPage(1); // Reset to first page when filters change
  };

  const totalPages = Math.ceil(totalCount / itemsPerPage);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Sticky Search and Filter Bar */}
      <div className="sticky top-[64px] z-10 bg-white border-b border-gray-200 shadow-sm">
        <div className="max-w-[1920px] mx-auto">
          {/* Search Section */}
          <div className="px-4 sm:px-6 py-3 sm:py-4 border-b border-gray-100 bg-white">
            <div className="relative">
              <input
                type="text"
                placeholder="Search projects..."
                className="w-full px-3 sm:px-4 py-2 sm:py-3 text-sm sm:text-base text-gray-900 placeholder-gray-500 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setCurrentPage(1);
                }}
              />
              <div className="absolute right-3 top-1/2 transform -translate-y-1/2">
                <svg className="w-4 h-4 sm:w-5 sm:h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
            </div>
          </div>

          {/* Filter Bar */}
          <div className="px-4 sm:px-6 py-2 sm:py-3 bg-white">
            <div className="flex items-center gap-2 sm:gap-4 overflow-x-auto pb-2 scrollbar-hide">
              <select 
                className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm text-gray-900 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[120px] sm:min-w-[140px] bg-white"
                value={filters.priceRange}
                onChange={(e) => handleFilterChange('priceRange', e.target.value)}
              >
                <option value="" className="text-gray-900">Price Range</option>
                <option value="0-5000000" className="text-gray-900">₹0 - ₹50L</option>
                <option value="5000000-10000000" className="text-gray-900">₹50L - ₹1Cr</option>
                <option value="10000000-20000000" className="text-gray-900">₹1Cr - ₹2Cr</option>
                <option value="20000000-50000000" className="text-gray-900">₹2Cr - ₹5Cr</option>
                <option value="50000000-100000000" className="text-gray-900">₹5Cr+</option>
              </select>

              <select 
                className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm text-gray-900 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[120px] sm:min-w-[140px] bg-white"
                value={filters.propertyType}
                onChange={(e) => handleFilterChange('propertyType', e.target.value)}
              >
                <option value="" className="text-gray-900">Property Type</option>
                <option value="apartment" className="text-gray-900">Apartment</option>
                <option value="house" className="text-gray-900">House</option>
                <option value="villa" className="text-gray-900">Villa</option>
                <option value="plot" className="text-gray-900">Plot</option>
                <option value="commercial" className="text-gray-900">Commercial</option>
              </select>

              <select 
                className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm text-gray-900 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[120px] sm:min-w-[140px] bg-white"
                value={filters.city}
                onChange={(e) => handleFilterChange('city', e.target.value)}
              >
                <option value="" className="text-gray-900">City</option>
                {cities.map(city => (
                  <option key={city} value={city} className="text-gray-900">{city}</option>
                ))}
              </select>

              {filters.city && (
                <select 
                  className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm text-gray-900 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[120px] sm:min-w-[140px] bg-white"
                  value={filters.locality}
                  onChange={(e) => handleFilterChange('locality', e.target.value)}
                >
                  <option value="" className="text-gray-900">Locality</option>
                  {localities.map(locality => (
                    <option key={locality} value={locality} className="text-gray-900">{locality}</option>
                  ))}
                </select>
              )}

              <select 
                className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm text-gray-900 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[120px] sm:min-w-[140px] bg-white"
                value={filters.status}
                onChange={(e) => handleFilterChange('status', e.target.value)}
              >
                <option value="" className="text-gray-900">Status</option>
                <option value="upcoming" className="text-gray-900">Upcoming</option>
                <option value="ongoing" className="text-gray-900">Ongoing</option>
                <option value="completed" className="text-gray-900">Completed</option>
              </select>

              <select 
                className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm text-gray-900 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[120px] sm:min-w-[140px] bg-white"
                value={filters.sortBy}
                onChange={(e) => handleFilterChange('sortBy', e.target.value)}
              >
                <option value="newest" className="text-gray-900">Newest First</option>
                <option value="price_asc" className="text-gray-900">Price: Low to High</option>
                <option value="price_desc" className="text-gray-900">Price: High to Low</option>
              </select>

              <button
                onClick={() => {
                  setFilters({
                    priceRange: '',
                    propertyType: '',
                    city: '',
                    locality: '',
                    status: '',
                    sortBy: 'newest'
                  });
                  setCurrentPage(1);
                }}
                className="px-2 sm:px-3 py-1.5 sm:py-2 text-sm font-medium text-gray-900 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors whitespace-nowrap"
              >
                Clear Filters
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1">
        <div className="max-w-[1920px] mx-auto px-4 sm:px-6 py-4 sm:py-6">
          {/* Page Title */}
          <h1 className="text-2xl sm:text-3xl font-bold mb-4 sm:mb-6 text-gray-900">Project Listings</h1>

          {/* Main Content with 70-30 Layout */}
          <div className="flex flex-col lg:flex-row gap-4 sm:gap-6">
            {/* Left Side - Projects List (70%) */}
            <div className="w-full lg:w-[70%]">
              {/* Results Grid */}
              {loading ? (
                <div className="space-y-4 sm:space-y-6">
                  {[...Array(4)].map((_, i) => (
                    <div key={i} className="bg-white rounded-lg shadow-md animate-pulse">
                      <div className="flex flex-col lg:flex-row">
                        <div className="lg:w-2/5 h-48 sm:h-56 bg-gray-200"></div>
                        <div className="flex-1 p-4 sm:p-6">
                          <div className="h-5 sm:h-6 bg-gray-200 rounded w-3/4 mb-3 sm:mb-4"></div>
                          <div className="h-4 bg-gray-200 rounded w-1/2 mb-2"></div>
                          <div className="h-4 bg-gray-200 rounded w-1/4 mb-3 sm:mb-4"></div>
                          <div className="h-4 bg-gray-200 rounded w-full mb-2"></div>
                          <div className="h-4 bg-gray-200 rounded w-2/3"></div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : projects.length === 0 ? (
                <div className="bg-white rounded-lg shadow-md p-8 text-center">
                  <div className="flex flex-col items-center justify-center space-y-4">
                    <svg 
                      className="w-16 h-16 text-gray-400" 
                      fill="none" 
                      stroke="currentColor" 
                      viewBox="0 0 24 24"
                    >
                      <path 
                        strokeLinecap="round" 
                        strokeLinejoin="round" 
                        strokeWidth={2} 
                        d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" 
                      />
                    </svg>
                    <h3 className="text-xl font-semibold text-gray-900">No Projects Available</h3>
                    <p className="text-gray-600 max-w-md">
                      {searchQuery || Object.values(filters).some(value => value !== '') 
                        ? "We couldn't find any projects matching your search criteria. Try adjusting your filters or search terms."
                        : "There are currently no projects listed. Please check back later for new listings."}
                    </p>
                    {(searchQuery || Object.values(filters).some(value => value !== '')) && (
                      <button
                        onClick={() => {
                          setSearchQuery('');
                          setFilters({
                            priceRange: '',
                            propertyType: '',
                            city: '',
                            locality: '',
                            status: '',
                            sortBy: 'newest'
                          });
                        }}
                        className="mt-4 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                      >
                        Clear All Filters
                      </button>
                    )}
                  </div>
                </div>
              ) : (
                <>
                  <div className="space-y-4 sm:space-y-6">
                    {projects.map((project) => {
                      const cardData = convertToCardData(project);
                      console.log('Passing to ProjectListingCard:', {
                        projectId: project.id,
                        cardData: {
                          developer_name: cardData.developer_name,
                          developer_id: cardData.developer_id
                        }
                      });
                      return (
                        <ProjectListingCard
                          key={project.id}
                          {...cardData}
                          isAuthenticated={!!user}
                          onSave={() => {
                            if (user) {
                              // TODO: Implement save project functionality
                              console.log('Saving project:', project.id);
                            } else {
                              window.location.href = '/auth?tab=login';
                            }
                          }}
                        />
                      );
                    })}
                  </div>

                  {/* Pagination */}
                  {totalPages > 1 && (
                    <div className="mt-6 sm:mt-8 flex justify-center gap-1 sm:gap-2">
                      <button
                        onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                        disabled={currentPage === 1}
                        className="px-3 sm:px-4 py-1.5 sm:py-2 text-sm rounded-lg border border-gray-300 disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                      >
                        Previous
                      </button>
                      {[...Array(totalPages)].map((_, i) => (
                        <button
                          key={i}
                          onClick={() => setCurrentPage(i + 1)}
                          className={`px-3 sm:px-4 py-1.5 sm:py-2 text-sm rounded-lg border ${
                            currentPage === i + 1
                              ? 'bg-blue-600 text-white border-blue-600'
                              : 'border-gray-300 hover:bg-gray-50'
                          }`}
                        >
                          {i + 1}
                        </button>
                      ))}
                      <button
                        onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                        disabled={currentPage === totalPages}
                        className="px-3 sm:px-4 py-1.5 sm:py-2 text-sm rounded-lg border border-gray-300 disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                      >
                        Next
                      </button>
                    </div>
                  )}
                </>
              )}
            </div>

            {/* Right Side - Sticky Ad Space (30%) - Hidden on Mobile */}
            <div className="hidden lg:block w-[30%]">
              <div className="sticky top-[200px] space-y-4 sm:space-y-6">
                {/* Featured Projects Section */}
                <div className="bg-white rounded-lg shadow-md p-4 sm:p-6">
                  <h2 className="text-lg sm:text-xl font-semibold text-gray-900 mb-3 sm:mb-4">Featured Project</h2>
                  {projects.length > 0 && (
                    <FeaturedProjectCard
                      id={projects[0].id}
                      name={projects[0].name}
                      city={projects[0].city?.name || 'Unknown City'}
                      locality={projects[0].locality?.name || 'Unknown Locality'}
                      starting_price={projects[0].price_range.min}
                      image_url={projects[0].cover_image_url || '/placeholder-project.jpg'}
                      status={projects[0].is_active ? 'active' : 'inactive'}
                      formattedPrice={`₹${projects[0].price_range.min.toLocaleString('en-IN')}`}
                    />
                  )}
                </div>

                {/* Ad Space */}
                <div className="bg-white rounded-lg shadow-md p-4 sm:p-6">
                  <h2 className="text-lg sm:text-xl font-semibold text-gray-900 mb-3 sm:mb-4">Advertisement</h2>
                  <div className="aspect-[4/5] bg-gray-100 rounded-lg flex items-center justify-center">
                    <p className="text-gray-500 text-sm">Ad Space</p>
                  </div>
                </div>

                {/* Quick Contact */}
                <div className="bg-white rounded-lg shadow-md p-4 sm:p-6">
                  <h2 className="text-lg sm:text-xl font-semibold text-gray-900 mb-3 sm:mb-4">Need Help?</h2>
                  <p className="text-sm sm:text-base text-gray-600 mb-3 sm:mb-4">Our team is here to help you find your dream property.</p>
                  <button
                    onClick={() => window.location.href = '/contact'}
                    className="w-full px-4 py-2 text-sm sm:text-base bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                  >
                    Contact Us
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer */}
      <Footer />
    </div>
  );
}